"""Curated interview question bank (authored content, not generated at request time).

Each question has a model answer, scoring key points (each with keywords used for coverage
checks), a practical example, follow-ups and, via ``criteria_for``, evaluation criteria.
Kinds: technical, architecture, system_design, engineering_leadership, engineering_management,
behavioural, scenario, hr.
"""

from __future__ import annotations

from dataclasses import dataclass

INTERVIEW_KINDS = (
    "technical", "engineering_leadership", "engineering_management", "architecture",
    "system_design", "behavioural", "scenario", "hr",
)

CRITERIA = {
    "technical": ["Technical accuracy", "Depth beyond definitions (why/trade-offs)", "Concrete real-world example"],
    "architecture": ["Clear trade-off analysis", "Awareness of failure modes and cost", "Fit to business context"],
    "system_design": ["Requirements clarified first", "Scalable, justified design", "Bottlenecks and failure handling"],
    "engineering_leadership": ["Influence without authority", "Clear communication", "Outcome-focused examples"],
    "engineering_management": ["People-first judgement", "Balances delivery and sustainability", "Specific examples and metrics"],
    "behavioural": ["STAR structure (Situation, Task, Action, Result)", "Your own actions ('I'), not just 'we'", "Measurable result and reflection"],
    "scenario": ["Prioritises mitigation and communication", "Structured approach", "Learning and prevention"],
    "hr": ["Honest and consistent", "Concise and positive", "Aligned with the role"],
}


@dataclass(frozen=True)
class KeyPoint:
    text: str
    keywords: tuple[str, ...]


@dataclass(frozen=True)
class Question:
    id: str
    kind: str
    topic: str
    difficulty: str
    question: str
    model_answer: str
    key_points: tuple[KeyPoint, ...]
    practical_example: str
    follow_ups: tuple[str, ...]

    @property
    def evaluation_criteria(self) -> list[str]:
        return CRITERIA[self.kind]


def _q(id_: str, kind: str, topic: str, diff: str, question: str, answer: str,
       points: list[tuple[str, tuple[str, ...]]], example: str, follow: list[str]) -> Question:
    return Question(id_, kind, topic, diff, question, answer,
                    tuple(KeyPoint(t, k) for t, k in points), example, tuple(follow))


